CREATE TABLE trg17_notes (note_id INTEGER PRIMARY KEY, note_text TEXT NOT NULL);
CREATE TABLE trg17_note_audit (audit_id INTEGER PRIMARY KEY, note_id INTEGER NOT NULL);
